package com.fireamun.iptv.core.storage

import java.security.GeneralSecurityException
import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/** Versioned authenticated envelope. Nonces are generated by the selected JCA provider. */
internal class AesGcm(private val key: () -> SecretKey) {
    fun seal(plaintext: ByteArray, context: String): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, key())
        cipher.updateAAD(context.toByteArray(Charsets.UTF_8))
        if (cipher.iv.size != 12) throw GeneralSecurityException("Protected storage unavailable")
        return byteArrayOf(1) + cipher.iv + cipher.doFinal(plaintext)
    }
    fun open(envelope: ByteArray, context: String): ByteArray {
        if (envelope.size < 29 || envelope[0] != 1.toByte()) throw GeneralSecurityException("Protected storage unavailable")
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, key(), GCMParameterSpec(128, envelope.copyOfRange(1, 13)))
        cipher.updateAAD(context.toByteArray(Charsets.UTF_8))
        return cipher.doFinal(envelope, 13, envelope.size - 13)
    }
}
